import idna


def encode_domain_name(s: str, uts46: bool = False) -> str:
    """Convert a Unicode domain name into its ASCII (A-label) form using IDNA 2008 encoding. s: The domain name to encode. uts46: If True, apply UTS #46 mapping before encoding. Example: encode_domain_name('example.测试') -> 'example.xn--fsq.xn--fiqs8s'."""
    try:
        result = idna.encode(s, uts46=uts46)
        return result.decode('ascii')
    except idna.core.IDNAError as e:
        raise ValueError(f"Failed to encode domain name: {str(e)}")

import idna


def convert_to_a_label(label: str) -> str:
    """Convert a single U-label into its A-label form. label: The label to convert, as a Unicode string, e.g. 'example' -> 'example'."""
    try:
        result = idna.alabel(label)
        return result.decode('ascii')
    except idna.IDNAError as e:
        raise ValueError(f"Invalid label: {label!r}") from e

