def check_bidi_rule(label: str, check_ltr: bool = False) -> bool:
    """Validate the Bidi Rule from RFC 5893 for a single label. label: The label to validate as a Unicode string. check_ltr: If True, apply the rules even when the label contains no RTL characters. Example: check_bidi_rule('example.com') -> True."""
    try:
        return idna.check_bidi(label, check_ltr)
    except IDNABidiError as e:
        raise ValueError(f"Bidi validation failed: {str(e)}") from e
    except Exception as e:
        raise ValueError(f"Invalid input: {str(e)}") from e

