import unicodedata
from idna import IDNAError


def check_nfc_normalization(label: str) -> None:
    """Require that a label is in Unicode Normalization Form C. label: The label to check, e.g. 'café' -> None."""
    try:
        if len(label) > 1000:  # Assuming _max_input_length is 1000 based on typical IDNA limits
            raise IDNAError("Label too long", code="input_too_long")
        if unicodedata.normalize("NFC", label) != label:
            raise IDNAError("Label must be in Normalization Form C", code="not_nfc")
    except IDNAError:
        raise ValueError(f"Label '{label}' is not in Unicode Normalization Form C")

