def apply_uts46_mapping(domain: str, std3_rules: bool = True) -> str:
    """Apply the UTS #46 character mapping to a domain string for compatibility. domain: The full domain name to remap according to UTS #46, std3_rules: If True, apply UTS #46's UseSTD3ASCIIRules. Example: apply_uts46_mapping('example.com') -> 'example.com'."""
    try:
        return idna.uts46_remap(domain, std3_rules=std3_rules)
    except Exception as e:
        raise ValueError(f"Failed to apply UTS #46 mapping: {str(e)}") from e

