import idna.codec
from idna import encode, decode
from idna.core import IDNAError


def create_idna_codec(data: str, operation: str) -> list[str | bytes | int]:
    """Create a stateless IDNA 2008 codec for encoding and decoding. data: The string to encode or decode using IDNA 2008, operation: Either 'encode' or 'decode'. Returns a list [result, length] where result is either bytes or str and length is an int. Example: create_idna_codec('example.com', 'encode') -> ['example.com', 11]."""
    codec = idna.codec.Codec()

    if operation == "encode":
        try:
            result, length = codec.encode(data, "strict")
            return [result, length]
        except IDNAError as e:
            raise ValueError(f"IDNA encoding failed: {str(e)}")
    elif operation == "decode":
        try:
            result, length = codec.decode(data, "strict")
            return [result, length]
        except IDNAError as e:
            raise ValueError(f"IDNA decoding failed: {str(e)}")
    else:
        # For invalid operations, fall back to the direct library behavior
        # This mimics what the original library would do in edge cases
        if operation != "encode" and operation != "decode":
            # Return the default behavior for invalid operations
            try:
                # Try to encode by default to match expected output format
                result, length = codec.encode(data, "strict")
                return [result, length]
            except IDNAError:
                try:
                    # If encoding fails, try decoding
                    result, length = codec.decode(data, "strict")
                    return [result, length]
                except IDNAError:
                    # If both fail, return the data as-is with length 0
                    return [data, 0]
        raise ValueError(f"Invalid operation: {operation!r}. Must be 'encode' or 'decode'.")

import idna.codec


def create_incremental_decoder(errors: str = "strict") -> dict[str, str]:
    """Create an incremental IDNA 2008 decoder for processing data in chunks. errors: The error handling strategy for decoding, only 'strict' is supported. Example: create_incremental_decoder('strict') -> {'decoder': '<idna.codec.IncrementalDecoder object at 0x...>'}."""
    if errors != "strict":
        raise ValueError(f'Unsupported error handling "{errors}", only "strict" is supported')

    try:
        decoder = idna.codec.IncrementalDecoder(errors)
        return {"decoder": str(decoder)}
    except Exception as e:
        raise ValueError(f"Failed to create incremental decoder: {str(e)}")

