def compat_to_unicode(label: str) -> str:
    """Compatibility shim for RFC 3490 ToUnicode. label: The label or domain to decode, e.g. 'example.com' -> 'example.com'."""
    try:
        return idna.decode(label)
    except Exception as e:
        raise ValueError(f"invalid label: {label!r}") from e
